module file_matcher(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] pattern_char,\n    input [7:0] filename_char,\n    input pattern_valid,\n    input filename_valid,\n    input pattern_end,\n    input filename_end,\n    output reg match,\n    output reg done\n);\n\n    // Parameters\n    localparam MAX_LEN = 16;\n\n    // State machine states\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] MATCH = 3'd1;\n    localparam [2:0] CHECK_STAR = 3'd2;\n    localparam [2:0] ADVANCE_BOTH = 3'd3;\n    localparam [2:0] ADVANCE_PATTERN = 3'd4;\n    localparam [2:0] ADVANCE_FILENAME = 3'd5;\n    localparam [2:0] BACKTRACK = 3'd6;\n    localparam [2:0] DONE = 3'd7;\n\n    // Registers\n    reg [2:0] state, next_state;\n    reg [7:0] pattern_reg [0:MAX_LEN-1];\n    reg [7:0] filename_reg [0:MAX_LEN-1];\n    reg [4:0] pattern_idx;\n    reg [4:0] filename_idx;\n    reg [4:0] star_idx;\n    reg [4:0] star_match_idx;\n    reg [4:0] pattern_len;\n    reg [4:0] filename_len;\n    reg processing;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start && pattern_valid && filename_valid) begin\n                    next_state = MATCH;\n                end\n            end\n            MATCH: begin\n                if (pattern_idx >= pattern_len && filename_idx >= filename_len) begin\n                    next_state = DONE;\n                end else if (pattern_idx >= pattern_len) begin\n                    next_state = DONE;\n                end else if (filename_idx >= filename_len) begin\n                    if (pattern_reg[pattern_idx] == 8'h2A) begin\n                        next_state = ADVANCE_PATTERN;\n                    end else begin\n                        next_state = DONE;\n                    end\n                end else if (pattern_reg[pattern_idx] == 8'h2A) begin\n                    next_state = CHECK_STAR;\n                end else if (pattern_reg[pattern_idx] == filename_reg[filename_idx] || pattern_reg[pattern_idx] == 8'h3F) begin\n                    next_state = ADVANCE_BOTH;\n                end else if (star_idx != 5'h1F) begin\n                    next_state = BACKTRACK;\n                end else begin\n                    next_state = DONE;\n                end\n            end\n            CHECK_STAR: begin\n                next_state = ADVANCE_PATTERN;\n            end\n            ADVANCE_BOTH: begin\n                next_state = MATCH;\n            end\n            ADVANCE_PATTERN: begin\n                next_state = MATCH;\n            end\n            ADVANCE_FILENAME: begin\n                next_state = MATCH;\n            end\n            BACKTRACK: begin\n                next_state = MATCH;\n            end\n            DONE: begin\n                if (!start) begin\n                    next_state = IDLE;\n                end\n            end\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Output and datapath logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            pattern_idx <= 0;\n            filename_idx <= 0;\n            star_idx <= 5'h1F;\n            star_match_idx <= 0;\n            match <= 0;\n            done <= 0;\n            processing <= 0;\n            pattern_len <= 0;\n            filename_len <= 0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start && pattern_valid && filename_valid) begin\n                        pattern_idx <= 0;\n                        filename_idx <= 0;\n                        star_idx <= 5'h1F;\n                        star_match_idx <= 0;\n                        match <= 0;\n                        done <= 0;\n                        processing <= 1;\n                        pattern_len <= 0;\n                        filename_len <= 0;\n                    end\n                end\n                CHECK_STAR: begin\n                    star_idx <= pattern_idx;\n                    star_match_idx <= filename_idx;\n                    pattern_idx <= pattern_idx + 1;\n                end\n                ADVANCE_BOTH: begin\n                    pattern_idx <= pattern_idx + 1;\n                    filename_idx <= filename_idx + 1;\n                end\n                ADVANCE_PATTERN: begin\n                    if (pattern_idx < pattern_len) begin\n                        pattern_idx <= pattern_idx + 1;\n                    end\n                end\n                ADVANCE_FILENAME: begin\n                    if (filename_idx < filename_len) begin\n                        filename_idx <= filename_idx + 1;\n                    end\n                end\n                BACKTRACK: begin\n                    pattern_idx <= star_idx + 1;\n                    filename_idx <= star_match_idx + 1;\n                    star_match_idx <= star_match_idx + 1;\n                end\n                DONE: begin\n                    if (pattern_idx >= pattern_len && filename_idx >= filename_len) begin\n                        match <= 1;\n                    end else begin\n                        match <= 0;\n                    end\n                    done <= 1;\n                    processing <= 0;\n                end\n            endcase\n            \n            // Buffer input characters\n            if (pattern_valid && processing) begin\n                if (pattern_len < MAX_LEN) begin\n                    pattern_reg[pattern_len] <= pattern_char;\n                    pattern_len <= pattern_len + 1;\n                end\n            end\n            if (filename_valid && processing) begin\n                if (filename_len < MAX_LEN) begin\n                    filename_reg[filename_len] <= filename_char;\n                    filename_len <= filename_len + 1;\n                end\n            end\n        end\n    end\n\nendmodule